require_once __DIR__.'/../includes/bootstrap.php';require_developer();require_once __DIR__.'/../includes/view_helpers.php';$id=(int)($_GET['id']??0);$project=project_owned($pdo,$id);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$desc=trim((string)($_POST['description']??''));$q=$pdo->prepare('SELECT project_id FROM projects WHERE user_id=? AND LOWER(name)=LOWER(?) AND project_id<>?');$q->execute([current_user()['user_id'],$name,$id]);if($name===''||$q->fetchColumn()){flash('danger',$name===''?'Project name is required.':'A project with this name already exists in your account.');go('project.php?id='.$id);}$q=$pdo->prepare('UPDATE projects SET name=?,description=? WHERE project_id=? AND user_id=?');$q->execute([$name,$desc,$id,current_user()['user_id']]);flash('success','Project details updated.');go('project.php?id='.$id);}
$q=$pdo->prepare('SELECT f.*,(SELECT COUNT(*) FROM dependencies d WHERE d.file_id=f.file_id) dependency_count FROM dependency_files f WHERE f.project_id=? ORDER BY f.uploaded_at DESC');$q->execute([$id]);$files=$q->fetchAll();$runs=scan_runs($pdo,$id);$compliance=compliance_for_scan($pdo,$id);page_header($project['name']);?>
